contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entrypoint for property test
    function run(uint128 sendEther, uint256 beforeValue) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendEther)); require(sendEther <= 1000000000000000000000000000000);
        require(address(this).balance >= sendEther);
        // read observable state before
        uint256 totalSupply_before = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 totalDistributed_before = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 balance_before = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        bool blacklisted_before = c.blacklist(address(this)); if (__ESBMC_reverted()) return;
        uint256 contractBalance_before = address(c).balance;

        // adjust the contract's public 'value' by calling nothing (we can't write it), but we can read it
        uint256 declaredValue_before = c.value(); if (__ESBMC_reverted()) return;

        // attempt to call getTokens sending ETH; catch revert
        bool reverted;
        c.getTokens{value: sendEther}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read observable state after
        uint256 totalSupply_after = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 totalDistributed_after = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 balance_after = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        bool blacklisted_after = c.blacklist(address(this)); if (__ESBMC_reverted()) return;
        uint256 contractBalance_after = address(c).balance;
        uint256 declaredValue_after = c.value(); if (__ESBMC_reverted()) return;

        // General rule to assert:
        // - totalSupply never increases
        // - if getTokens succeeded (not reverted) then caller's balance increased by at most the declared value before the call,
        //   totalDistributed increased by that same amount, and caller became blacklisted (blacklist true after)
        // - if it reverted, contract state did not change (conservative: totalSupply same and balances same and totalDistributed same)
        assert(
            // totalSupply never increases
            totalSupply_after <= totalSupply_before
            && (
                // case: reverted => no changes to balances/totalDistributed/contractBalance/blacklist
                (reverted
                    && totalDistributed_after == totalDistributed_before
                    && balance_after == balance_before
                    && contractBalance_after == contractBalance_before
                    && blacklisted_after == blacklisted_before
                )
                ||
                // case: not reverted => changes consistent with minting at most declaredValue_before
                (!reverted
                    && totalDistributed_after >= totalDistributed_before
                    && totalDistributed_after - totalDistributed_before == balance_after - balance_before
                    && balance_after - balance_before <= declaredValue_before
                    && blacklisted_after == true
                )
            )
        );
    }

    receive() external payable {}
}

