pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function _run(uint128 sendEther, uint256 beforeValue) internal {
        sendEther = uint128(bound(uint256(sendEther), 0, 1000000000000000000000000000000));
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendEther);
        uint256 totalSupply_before;
        try c.totalSupply() returns (uint256 __r) { totalSupply_before = __r; } catch { return; }
        uint256 totalDistributed_before;
        try c.totalDistributed() returns (uint256 __r) { totalDistributed_before = __r; } catch { return; }
        uint256 balance_before;
        try c.balanceOf(address(this)) returns (uint256 __r) { balance_before = __r; } catch { return; }
        bool blacklisted_before;
        try c.blacklist(address(this)) returns (bool __r) { blacklisted_before = __r; } catch { return; }
        uint256 contractBalance_before = address(c).balance;
        uint256 declaredValue_before;
        try c.value() returns (uint256 __r) { declaredValue_before = __r; } catch { return; }
        bool reverted;
        try c.getTokens{value: sendEther}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 totalSupply_after;
        try c.totalSupply() returns (uint256 __r) { totalSupply_after = __r; } catch { return; }
        uint256 totalDistributed_after;
        try c.totalDistributed() returns (uint256 __r) { totalDistributed_after = __r; } catch { return; }
        uint256 balance_after;
        try c.balanceOf(address(this)) returns (uint256 __r) { balance_after = __r; } catch { return; }
        bool blacklisted_after;
        try c.blacklist(address(this)) returns (bool __r) { blacklisted_after = __r; } catch { return; }
        uint256 contractBalance_after = address(c).balance;
        uint256 declaredValue_after;
        try c.value() returns (uint256 __r) { declaredValue_after = __r; } catch { return; }
        assertTrue(totalSupply_after <= totalSupply_before
            && (
                // case: reverted => no changes to balances/totalDistributed/contractBalance/blacklist
                (reverted
                    && totalDistributed_after == totalDistributed_before
                    && balance_after == balance_before
                    && contractBalance_after == contractBalance_before
                    && blacklisted_after == blacklisted_before
                )
                ||
                // case: not reverted => changes consistent with minting at most declaredValue_before
                (!reverted
                    && totalDistributed_after >= totalDistributed_before
                    && totalDistributed_after - totalDistributed_before == balance_after - balance_before
                    && balance_after - balance_before <= declaredValue_before
                    && blacklisted_after == true
                )
            ));
    }

    function testFuzz_run(uint128 sendEther, uint256 beforeValue) public {
        _run(sendEther, beforeValue);
    }

    receive() external payable {}
}
